import{_ as e,c as a,o as t,a4 as r}from"./chunks/framework.DzOtv0XR.js";const f=JSON.parse('{"title":"Web 前端安全","description":"","frontmatter":{},"headers":[],"relativePath":"web/security.md","filePath":"web/security.md"}'),i={name:"web/security.md"},l=r('<h1 id="web-前端安全" tabindex="-1">Web 前端安全 <a class="header-anchor" href="#web-前端安全" aria-label="Permalink to &quot;Web 前端安全&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#xss-跨站脚本攻击">XSS 跨站脚本攻击</a><ul><li><a href="#dom-型-xss-前端关注">DOM 型 XSS（前端关注）</a></li></ul></li><li><a href="#csrf-跨站请求伪造">CSRF 跨站请求伪造</a></li><li><a href="#点击劫持-clickjacking">点击劫持（ClickJacking）</a></li><li><a href="#http-劫持">HTTP 劫持</a></li><li><a href="#混合内容-http-https">混合内容（http + https）</a></li><li><a href="#cookie-相关">cookie 相关</a></li><li><a href="#crypto">Crypto</a></li><li><a href="#中间人攻击">中间人攻击</a></li><li><a href="#速查">速查</a></li><li><a href="#源码混淆">源码混淆</a></li></ul></nav><p>crypto, TSL/SSL HTTPS XSS</p><h2 id="xss-跨站脚本攻击" tabindex="-1">XSS 跨站脚本攻击 <a class="header-anchor" href="#xss-跨站脚本攻击" aria-label="Permalink to &quot;XSS 跨站脚本攻击&quot;">​</a></h2><p>在网页中植入恶意脚本，输入源有脚本参数、表单提交</p><p>危害：获取用户 cookie</p><p>解决方式：</p><ul><li>HttpOnly，无法通过 JS 读、改、删 Cookie</li><li>CSP 内容安全策略</li></ul><p>设置 header，做哈希验证</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>content-security-policy: script-src &#39;sha256-wxWy1+9LmiuOeDwtQyZNmWpT0jqCUikqaqVlJdtdh/0=&#39;</span></span></code></pre></div><p>避免使用<code>eval</code></p><p>Self-XSS 欺骗用户在控制台运行恶意代码</p><p>谷歌翻译的做法，在控制台显示信息警告用户</p><p><strong>转义为实体字符</strong>，正则替换</p><p>vue 使用 he 库  (for “HTML entities”)</p><p>常规变量、属性，vue 会转义，但 v-html 需要使用者自己保证，避免使用</p><blockquote><p>最基本的规则就是只要你允许执行未经无害化处理的、用户提供的内容 (无论是 HTML、JavaScript 还是 CSS)，你就可能面临攻击。</p></blockquote><p><a href="https://cn.vuejs.org/guide/best-practices/security.html#potential-dangers" target="_blank" rel="noreferrer">安全 | Vue.js</a></p><h3 id="dom-型-xss-前端关注" tabindex="-1">DOM 型 XSS（前端关注） <a class="header-anchor" href="#dom-型-xss-前端关注" aria-label="Permalink to &quot;DOM 型 XSS（前端关注）&quot;">​</a></h3><p>使用 Vue 强转成字符串，不会有问题.</p><p><a href="https://segmentfault.com/a/1190000039713551" target="_blank" rel="noreferrer">Vue中是如何防御XSS（注入攻击）的 - SegmentFault 思否 </a></p><p>通用的规则是只要允许执行未过滤的用户提供的内容 (不论作为 HTML、JavaScript 甚至 CSS)，你就可能令自己处于被攻击的境地。这些建议实际上不论使用 Vue 还是别的框架甚至不使用框架，都是成立的。- <a href="https://cn.vuejs.org/v2/guide/security.html" target="_blank" rel="noreferrer">安全 — Vue.js</a></p><p><a href="https://insights.thoughtworks.cn/web-frontend-security/" target="_blank" rel="noreferrer">WEB前端安全自查和加固 - Thoughtworks洞见</a></p><p><a href="https://codepen.io/cyio/pen/gOXbZaa" target="_blank" rel="noreferrer">XSS payload DEMO</a></p><h2 id="csrf-跨站请求伪造" tabindex="-1">CSRF 跨站请求伪造 <a class="header-anchor" href="#csrf-跨站请求伪造" aria-label="Permalink to &quot;CSRF 跨站请求伪造&quot;">​</a></h2><p>伪造请求</p><p>第三方域名页面，发起合法请求，服务器没有做来源过滤。举例，合法调用接口设置 Gmail 转发，获取隐私邮件</p><p>解决：</p><ul><li>同源检查 origin/referer</li><li>CSRF Token，如表单提交必须带上 token。原理是攻击者只带 cookie 无法请求成功</li><li>交互验证码（短信炸弹）</li></ul><p><a href="https://tech.meituan.com/2018/10/11/fe-security-csrf.html" target="_blank" rel="noreferrer">前端安全系列（二）：如何防止CSRF攻击？ - 美团技术团队</a></p><h2 id="点击劫持-clickjacking" tabindex="-1">点击劫持（ClickJacking） <a class="header-anchor" href="#点击劫持-clickjacking" aria-label="Permalink to &quot;点击劫持（ClickJacking）&quot;">​</a></h2><p>X-Frame-Options 防止页面被嵌入恶意利用</p><p><a href="https://segmentfault.com/a/1190000037657222" target="_blank" rel="noreferrer">前端安全编码规范 - SegmentFault 思否</a></p><h2 id="http-劫持" tabindex="-1">HTTP 劫持 <a class="header-anchor" href="#http-劫持" aria-label="Permalink to &quot;HTTP 劫持&quot;">​</a></h2><p>内容未加密，页面被插入内容，如弹窗</p><p>应对：升级 HTTPS 内容加密</p><h2 id="混合内容-http-https" tabindex="-1">混合内容（http + https） <a class="header-anchor" href="#混合内容-http-https" aria-label="Permalink to &quot;混合内容（http + https）&quot;">​</a></h2><ul><li>被动 image/media 威胁性低，可访问，但锁、控制台会提示</li><li>主动 script style iframe flash 拦截</li></ul><p><a href="https://developers.google.com/web/fundamentals/security/prevent-mixed-content/what-is-mixed-content" target="_blank" rel="noreferrer">什么是混合内容？  |  Web  |  Google Developers</a></p><h2 id="cookie-相关" tabindex="-1">cookie 相关 <a class="header-anchor" href="#cookie-相关" aria-label="Permalink to &quot;cookie 相关&quot;">​</a></h2><ul><li>HttpOnly 限制 cookie 只能发请求携带，禁用 JS 读取。服务端设置<code>Set-Cookie</code>，减轻 XSS 攻击</li><li>SameSite 减轻 CSRF 攻击</li><li>会话 cookie（默认），页面关闭时移除</li><li>常驻 cookie</li></ul><h2 id="crypto" tabindex="-1">Crypto <a class="header-anchor" href="#crypto" aria-label="Permalink to &quot;Crypto&quot;">​</a></h2><p>敏感数据加密保存</p><h2 id="中间人攻击" tabindex="-1">中间人攻击 <a class="header-anchor" href="#中间人攻击" aria-label="Permalink to &quot;中间人攻击&quot;">​</a></h2><p><a href="https://zh.wikipedia.org/wiki/%25E4%25B8%25AD%25E9%2597%25B4%25E4%25BA%25BA%25E6%2594%25BB%25E5%2587%25BB" target="_blank" rel="noreferrer">中间人攻击 - 维基百科，自由的百科全书</a></p><p>证书校验</p><p><a href="https://github.com/SFLAQiu/web-develop/blob/master/%25E5%25A4%25A7%25E8%25AF%259DWEB%25E5%25AE%2589%25E5%2585%25A8.md" target="_blank" rel="noreferrer">web-develop/大话WEB安全.md at master · SFLAQiu/web-develop</a></p><p>2022 Frontend security in 1 tweet:</p><ol><li>Use HTTPs</li><li>Server render</li><li>Store JWT/token in &#39;secure&#39;, &#39;samesite&#39;, &#39;httponly&#39; cookie (prevent XSS).</li><li>Declare content security policy (prevent XSS)</li><li>Regen cookies when user auths (prevent session fixation)</li><li>Set short cookie lifetime</li></ol><h2 id="速查" tabindex="-1">速查 <a class="header-anchor" href="#速查" aria-label="Permalink to &quot;速查&quot;">​</a></h2><p><a href="https://cheatsheetseries.owasp.org/cheatsheets/HTML5_Security_Cheat_Sheet.html#sandboxed-frames" target="_blank" rel="noreferrer">HTML5 Security - OWASP Cheat Sheet Series</a></p><p><a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">Cross Site Scripting Prevention - OWASP Cheat Sheet Series</a></p><h2 id="源码混淆" tabindex="-1">源码混淆 <a class="header-anchor" href="#源码混淆" aria-label="Permalink to &quot;源码混淆&quot;">​</a></h2><p>源码混淆可以极大的降低你的源码的可读性和可调试性，同时也会在不同程度上带来性能损耗，这也是为什么几乎所有现代前端开发框架（的脚手架）都不直接提供源码混淆的支持，需要开发者自己安排混淆插件。</p><p>Facebook完全是依靠服务端的逻辑来防范这些攻击的，几乎不会投入资源去做客户端的加密混淆这种工作。</p><p>electron的这套运行逻辑注定其安全性极差，无论你搞再多混淆还是其他花样，你给v8解析的时候你不能让v8不认识，也就是说必定可以搞到源码。 理论上你只要找到v8解析js的函数，在里面下断就可以dump出所有源码，如果觉得这种方法麻烦，现在网上有开源的解包项目，可以直接解包，修改源码再打包。</p>',56),o=[l];function s(h,p,n,c,d,u){return t(),a("div",null,o)}const k=e(i,[["render",s]]);export{f as __pageData,k as default};
